static inline float sigmoidf_fast(float x) {
  if (x >= 35.0f) return 1.0f;
  if (x <= -35.0f) return 0.0f;
  return 1.0f / (1.0f + expf(-x));
}

float xgboost_predict_probability(const double features[XGBOOST_MODEL_DIMS]) {
  float margin = kBaseMargin;
  (void)kNodeCount;
  for (uint32_t t = 0; t < kTreeCount; t++) {
    int32_t idx = (int32_t)kTreeOffsets[t];
    while (idx >= 0) {
      const XGBNode node = kNodes[idx];
      if (node.feature < 0) {
        margin += node.leaf;
        break;
      }
      const float fv = (float)features[node.feature];
      idx = (fv < node.threshold) ? node.left : node.right;
    }
  }
  return sigmoidf_fast(margin);
}

uint8_t xgboost_predict_fraud_count(const double features[XGBOOST_MODEL_DIMS]) {
  const float prob = xgboost_predict_probability(features);
  return (prob >= kFraudThreshold) ? 5 : 0;
}
